use gba_core::{Machine,Bus,ffta_battle_mouse as mouse};
use std::io::Write;
fn load(rom:&[u8])->Machine{let mut m=Machine::new(rom.to_vec());for(n,d)in[("ewram",&mut m.bus.ewram),("iwram",&mut m.bus.iwram),("vram",&mut m.bus.vram),("io",&mut m.bus.io),("oam",&mut m.bus.oam),("palette",&mut m.bus.palette)]{d.copy_from_slice(&std::fs::read(format!("target/bank-populated-{n}.bin")).unwrap());}m.bus.ffta_movement.enabled=true;m.bus.ffta_movement.europe_profile=true;m.bus.ffta_dialogue.separate=true;assert!(m.bus.ffta_battle_mouse.enable_replay());m}
fn render(m:&mut Machine){for y in 0..160{gba_core::ppu::render_scanline(&mut m.bus,y);}}
fn call(m:&mut Machine,pc:u32,r0:u32,r1:u32){m.bus.write32(0x03002bcc,0);m.cpu.cpsr=0xbf;m.cpu.regs[13]=0x03007b00;m.cpu.regs[14]=0x08000001;m.cpu.regs[15]=pc;m.cpu.regs[0]=r0;m.cpu.regs[1]=r1;m.cpu.branch=None;for _ in 0..12000000{if m.cpu.regs[15]==0x08000000{return;}if matches!(m.cpu.regs[15],0x08000b52|0x08000b0e){
let mut at=m.bus.read32(0x03002bcc);let mut seen=std::collections::BTreeSet::new();while at!=0 && seen.insert(at){let src=m.bus.read32(at+4);let dst=m.bus.read32(at+8);let cnt=m.bus.read32(at+12);let next=m.bus.read32(at+24);m.bus.write32(0x040000d4,src);m.bus.write32(0x040000d8,dst);m.bus.write32(0x040000dc,cnt|0x80000000);at=next;}m.bus.write32(0x03002bcc,0);
}if m.cpu.regs[15]==0x0805c0ea{let before=m.bus.ffta_dialogue.pixels.clone();render(m);assert_eq!(m.bus.ffta_dialogue.pixels,before,"partial bank page visible");}m.step();}panic!("call timeout pc={:x} regs={:x?}",m.cpu.regs[15],m.cpu.regs);}
fn ppm(m:&Machine,name:&str){let mut f=std::fs::File::create(format!("target/{name}.ppm")).unwrap();write!(f,"P6\n480 160\n255\n").unwrap();for y in 0..160{for x in 0..480{let p=m.bus.ffta_dialogue.pixels[y*480+x];let color=if p.visible(){p.color}else{0x4210};f.write_all(&[((color&31)*255/31)as u8,(((color>>5)&31)*255/31)as u8,(((color>>10)&31)*255/31)as u8]).unwrap();}}}
fn main(){let rom=std::fs::read(std::env::args().nth(1).unwrap()).unwrap();let mut m=load(&rom);gba_core::mem::set_extra(22);render(&mut m);println!("SCENE {:?} LIST {:?}",gba_core::ffta_ui::Scene::capture(&m.bus.ffta_dialogue),mouse::pub_list(&m.bus));assert_eq!(gba_core::ffta_ui::Scene::capture(&m.bus.ffta_dialogue).nodes[0].unwrap().bounds,[0,0,240,160]);assert!(gba_core::ffta_ui::Scene::capture(&m.bus.ffta_dialogue).nodes[2].is_none(),"preview must not become Clan Funds");ppm(&m,"bank-preview-fixed");let list=mouse::pub_list(&m.bus).unwrap();assert_eq!((list.total,list.visible),(20,7));let state=0x02023c54;
let mut world=load(&rom);let plane=std::fs::read("target/bank-live-stage.bin").unwrap();for bg in 0..2 {let off=bg*8+4;world.bus.ffta_stage.bases[bg]=Some(u32::from_le_bytes(plane[off..off+4].try_into().unwrap()));let off=16+bg*12;let ox=i32::from_le_bytes(plane[off+4..off+8].try_into().unwrap());let oy=i32::from_le_bytes(plane[off+8..off+12].try_into().unwrap());world.bus.ffta_stage.origins[bg]=Some((ox,oy));world.bus.ffta_stage.valid[bg]=true;}
gba_core::mem::set_extra(164);gba_core::mem::set_extra_y(80);render(&mut world);gba_core::ppu::render_ffta_zoom_rows(&mut world.bus);let mut f=std::fs::File::create("target/bank-world-actual-fixed.ppm").unwrap();write!(f,"P6\n568 320\n255\n").unwrap();for &c in &world.bus.wide_framebuffer[..568*320]{f.write_all(&[((c&31)*255/31)as u8,(((c>>5)&31)*255/31)as u8,(((c>>10)&31)*255/31)as u8]).unwrap();}gba_core::mem::set_extra(22);gba_core::mem::set_extra_y(0);

for t in [0,6,2,5]{assert!(mouse::menu_select(&mut m.bus,t,false));assert_eq!(mouse::MenuScene::read(&m.bus).unwrap().selected,t);assert_eq!(mouse::keys(&mut m.bus,0x3ff),0x3ff);m.bus.iwram[..8].fill(0);call(&mut m,0x0805b624,0,state);render(&mut m);assert_eq!(mouse::MenuScene::read(&m.bus).unwrap().selected,t);assert_eq!(m.bus.read8(0x02022f64+0x1bb6),t);m.bus.ffta_battle_mouse.cancel();println!("BANK populated target={t} direct=true model=true");}
for first in [7,13,3,0]{assert!(mouse::pub_scroll_to(&mut m.bus,first));m.bus.iwram[..8].fill(0);call(&mut m,0x0805b624,0,state);render(&mut m);assert_eq!(mouse::pub_list(&m.bus).unwrap().first,first);println!("BANK scroll first={first} page_complete=true");}
}
